function CommonLackMaterialItem:FreshStarUI(goodsId)
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
    if not goodsVo then
        return
    end
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting4070, "GoodsShowTypeVo", goodsVo.showType)
    local isShowStar
    if vo then
        isShowStar = (checkNumber(vo.showStar) == 1)
    end
    CfUtils.SetActive(self.StarGroup, isShowStar)

    if isShowStar then
        local num = checkNumber(goodsVo.quality)
        KTool.DestroyGameObjectChildren(self.StarGroup.gameObject, false)
        for i = 1, num do
            local go = KTool.Instantiate(self.StarGroup.gameObject, self.ImgStar.gameObject, false)
            CfUtils.SetActive(go, true)
        end
    end
end

---RefreshUI
---@param goodsData table {goodsId = xx, num = xx, gainNum = xx}
function CommonLackMaterialItem:RefreshUI(goodsData)
    
    local goodsId, num, gainNum = goodsData.goodsId, checkInt(goodsData.num), checkInt(goodsData.gainNum)
    local vo = goodsConfMgr:GetGoodsVoById(goodsId)
    self:RefreshGoodsNode(goodsId, vo)
    --self.TxtGoodName.text = vo.name
    self:FreshStarUI(goodsId)
    -- local ownNum = GoodsUtils.GetThingNo(goodsId)
    if self.NeedGroup then
        KTool.SetActive(self.NeedGroup.gameObject, gainNum > 0)
    end
    self.TxtNumber.text = gainNum

    self:RefreshEntranceGroupUI(vo.jumpAway, vo, gainNum)
end

function CommonLackMaterialItem:RefreshGoodsNode(goodsId, vo)
    ---@type GoodNodeMB
    local env = CfUtils.GetLuaScr(self.GoodNode, GoodNodeMBEnvPath)
    if isNull(env) then return end

    env:Reload({goodsId = goodsId, isShowNo = false})
    env:SetClickButtonAction(function()
        GameUtils.ShowCommonTipsBoard(self.GoodNode.gameObject, vo.name, vo.desc, vo.quality, vo.id)
    end)
end

---RefreshJumpAwayUI
---刷新获取途径UI
---@param jumpAway table
function CommonLackMaterialItem:RefreshEntranceGroupUI(jumpAway, vo, gainNum)
    local childCount = self.EntranceGroup.childCount
    for i = 1, JumpAwayMaxCount do
        local node
        if childCount >= i then
            node = self.EntranceGroup:GetChild(i - 1)
        else
            node = self.EntranceGroup.gameObject:AddChild(self.Entrance.gameObject)
        end

        local funcSwitchId = nil
        if jumpAway and jumpAway[i] then
            funcSwitchId = jumpAway[i]
        end
        self:RefreshEntranceNode(node.gameObject, funcSwitchId, vo, i, gainNum)
        
    end
end

---RefreshEntranceNode
---@param gameObject UnityEngine.GameObject
---@param funcSwitchId number 功能切割表id
function CommonLackMaterialItem:RefreshEntranceNode(gameObject, funcSwitchId, vo, index, gainNum)
    ---@type CommonLackMaterialItemEntranceNode
    local env = CfUtils.GetLuaScr(gameObject, EntranceNodeEnvPath)
    if isNull(env) then return end
    env:RefreshUI(funcSwitchId, vo, index, gainNum)
end

